def memoize(fn):
    """Cache results for every distinct combination of arguments,
    so repeated calls never recompute.
    """
    cache = {}
    def wrapper(*args, **kwargs):
        if args not in cache:
            cache[args] = fn(*args, **kwargs)
        return cache[args]
    return wrapper

@memoize
