def caesar_cipher(text, shift):
    """Shifts each letter by `shift` positions, wrapping within the alphabet,
    leaves non-letters unchanged, and preserves the original case of each letter.
    """
    result = []
    for ch in text:
        if ch.isalpha():
            shifted = chr((ord(ch.lower()) - ord('a') + shift) % 26 + ord('a'))
            result.append(shifted)
        else:
            result.append(ch)
    return ''.join(result)
```

